    elif hp <= 6:
        urgency += 1
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    tight_supply = supply <= 18
    very_tight = supply <= 16

    if budget <= 0:
        return 0.0

    if not alive:
        base = DAILY_SALARY * 0.22
